"""
Data Point Schema Definitions using JSON Schema
Provides database-friendly schema definitions for data collection
"""

from enum import Enum
from typing import Any, Dict

# JSON Schema definitions for each data point type
# These can be stored in a database and validated dynamically

class DataPointKey(str, Enum):
    """Registry of available data point keys"""
    FIRST_NAME = "first_name"
    LEGAL_NAME = "legal_name"
    MIN_PAY = "min_pay"
    PAY_RATE = "pay_rate"
    YEARS_EXPERIENCE = "years_experience"
    EDUCATION_LEVEL = "education_level"
    IS_CURRENTLY_WORKING = "is_currently_working"
    START_AVAILABILITY = "start_availability"
    WORK_AUTHORIZATION = "work_authorization"
    ZIP_CODE = "zip_code"
    HAS_TRANSPORTATION = "has_transportation"
    HAS_CRIMINAL_RECORD = "has_criminal_record"
    CURRENT_LOCATION = "current_location"
    RELOCATION_WILLINGNESS = "relocation_willingness"
    REMOTE_PREFERENCE = "remote_preference"
    SALARY_EXPECTATIONS = "salary_expectations"
    CURRENT_COMPENSATION = "current_compensation"
    AVAILABILITY_DATE = "availability_date"
    NOTICE_PERIOD = "notice_period"
    EMAIL = "email"
