    """Get the JSON schema for a data point key"""
    return DATA_POINT_SCHEMAS.get(key)


def validate_data_point(key: str, data: dict[str, Any]) -> tuple[bool, str | None]:
    """
    Validate data against a schema (simplified validation).
    Returns (is_valid, error_message)

    Note: For production, use jsonschema library for full validation
    """
    schema = get_schema(key)
    if not schema:
        return False, f"No schema found for key: {key}"

