        "required": ["value"],
        "additionalProperties": False,
        "metadata": {
            "display_name": "Legal Name",
            "category": "personal_info",
            "tool_description": "full legal name of the person",
        },
    },
    DataPointKey.MIN_PAY: {
        "type": "object",
        "properties": {
            "value": {
                "type": "number",
                "description": "Minimum pay rate expected",
                "minimum": 0,
                "maximum": 1000000,
            },
            "currency": {
                "type": "string",
                "description": "Currency code",
                "default": "USD",
                "enum": ["USD", "EUR", "GBP", "CAD", "AUD"],
            },
            "period": {
                "type": "string",
                "description": "Pay period",
                "default": "hourly",
